package com.example.recoveryfield
import android.app.*;import android.content.*;import java.text.SimpleDateFormat;import java.util.*;import com.example.recoveryfield.data.AppDb
import kotlinx.coroutines.launch
fun scheduleReminder(c:Context){val am=c.getSystemService(AlarmManager::class.java);val i=Intent(c,ReminderReceiver::class.java);val pi=PendingIntent.getBroadcast(c,777,i,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val cal=Calendar.getInstance().apply{set(Calendar.HOUR_OF_DAY,8);set(Calendar.MINUTE,0);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0);if(before(Calendar.getInstance()))add(Calendar.DAY_OF_YEAR,1)};am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,cal.timeInMillis,pi)}
class ReminderReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent?){val go=goAsync();kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.IO).launch{val db=AppDb.get(c);val today=SimpleDateFormat("yyyy-MM-dd",Locale.US).format(Date());val f=db.followUpDao().due(today);if(f.isNotEmpty()){val nm=c.getSystemService(NotificationManager::class.java);val ch="followups";if(android.os.Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(NotificationChannel(ch,"Recovery Follow-ups",NotificationManager.IMPORTANCE_DEFAULT));val n=Notification.Builder(c,ch).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Recovery Follow-up Due Today").setContentText("${f.size} account(s) scheduled for follow-up today").setAutoCancel(true).build();nm.notify(1001,n)};scheduleReminder(c);go.finish()}}}
class BootReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent?){scheduleReminder(c)}}
